node -e "
const db = require('better-sqlite3')('/workspace/world.db');

const cartId = 'CART-user_be7538d5';
const cartItemId = 'CI-0032';
const productPrice = 88;
const quantity = 2;

// Delete the cart item
db.prepare('DELETE FROM cart_items WHERE cart_item_id = ?').run(cartItemId);

// Update cart totals and item_ids_json
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
const newSubtotal = cart.subtotal - (productPrice * quantity);
const newTotal = newSubtotal - cart.discount_amount + cart.gift_wrap_fee - cart.loyalty_discount + cart.shipping_cost;
const itemIds = JSON.parse(cart.item_ids_json).filter(id => id !== cartItemId);

db.prepare('UPDATE carts SET subtotal = ?, total = ?, item_ids_json = ? WHERE cart_id = ?').run(newSubtotal, newTotal, JSON.stringify(itemIds), cartId);

// Verify
const updatedCart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
console.log('Updated Cart:', JSON.stringify(updatedCart, null, 2));
const items = db.prepare('SELECT * FROM cart_items WHERE cart_id = ?').all(cartId);
console.log('Remaining Items:', JSON.stringify(items, null, 2));
"
